This test currently asserts that when `terminal_suspend` is explicitly set on Windows, `input_undo` should *not* include Ctrl+Z. Since the `terminal_suspend` command is disabled on win32, that expectation makes Ctrl+Z a no-op by default (unless the user also overrides `input_undo`). If the intent is “Ctrl+Z undoes on Windows”, consider updating this expectation (and adding a case for an explicit `terminal_suspend: "ctrl+z"`) so Ctrl+Z still maps to undo unless `input_undo` is explicitly overridden.
```suggestion
      expect(config.keybinds?.input_undo).toBe("ctrl+z,ctrl+-,super+z")
    },
  })
})

wintest("keeps Ctrl+Z mapped to input undo when terminal suspend is explicitly set to Ctrl+Z on Windows", async () => {
  await using tmp = await tmpdir({
    init: async (dir) => {
      await Bun.write(path.join(dir, "tui.json"), JSON.stringify({ keybinds: { terminal_suspend: "ctrl+z" } }))
    },
  })

  await Instance.provide({
    directory: tmp.path,
    fn: async () => {
      const config = await TuiConfig.get()
      expect(config.keybinds?.terminal_suspend).toBe("ctrl+z")
      expect(config.keybinds?.input_undo).toBe("ctrl+z,ctrl+-,super+z")
    },
  })
})
```
